const items = $input.all();

const results = [];

for (const item of items) {
  const p = item.json;

  const income = Number(p.monthly_income);
  const creditScore = Number(p.credit_score);
  const age = Number(p.age);

  const minIncome = p.min_income === null ? 0 : Number(p.min_income);
  const minCredit = p.min_credit_score === null ? 0 : Number(p.min_credit_score);
  const maxCredit = p.max_credit_score === null ? 900 : Number(p.max_credit_score);
  const minAge = p.min_age === null ? 18 : Number(p.min_age);
  const maxAge = p.max_age === null ? 100 : Number(p.max_age);

  // Income eligibility
  const incomeEligible = income >= minIncome;

  // Credit score eligibility
  const creditEligible =
    creditScore >= minCredit &&
    creditScore <= maxCredit;

  // Age eligibility
  const ageEligible =
    age >= minAge &&
    age <= maxAge;

  // Employment eligibility
  let employmentEligible = true;

  if (Array.isArray(p.employment_required) &&
      p.employment_required.length > 0) {

      const normalizeEmployment = value => String(value).toLowerCase().replace(/[\s_-]+/g, '');

      const allowed = p.employment_required.map(normalizeEmployment);

      const employment = normalizeEmployment(p.employment_status);

      employmentEligible =
        allowed.includes('both') ||
        allowed.includes(employment);
  }

  const hardEligible =
    incomeEligible &&
    creditEligible &&
    ageEligible &&
    employmentEligible;

  // Calculate a simple score out of 100
  let score = 0;

  if (incomeEligible) score += 30;
  if (creditEligible) score += 30;
  if (ageEligible) score += 20;
  if (employmentEligible) score += 20;

  let matchStage;

  if (hardEligible) {
    matchStage = 'eligible';
  } else if (score >= 60) {
    matchStage = 'borderline';
  } else {
    matchStage = 'rejected';
  }

  results.push({
    json: {
      ...p,

      income_eligible: incomeEligible,
      credit_eligible: creditEligible,
      age_eligible: ageEligible,
      employment_eligible: employmentEligible,

      score,
      match_stage: matchStage,

      reason:
        `Income: ${incomeEligible ? 'pass' : 'fail'}; ` +
        `Credit: ${creditEligible ? 'pass' : 'fail'}; ` +
        `Age: ${ageEligible ? 'pass' : 'fail'}; ` +
        `Employment: ${employmentEligible ? 'pass' : 'fail'}`
    }
  });
}

return results;

const items = $input.all();

return items.map(item => {
  const p = item.json;

  return {
    json: {
      user_id: p.user_id,
      product_id: p.product_id,

