      min_income: p.min_income,
      min_credit_score: p.min_credit_score,
      max_credit_score: p.max_credit_score,
      min_age: p.min_age,
      max_age: p.max_age,

      employment_required: p.employment_required,
      eligibility_notes: p.eligibility_notes,

      deterministic_score: p.score,
      deterministic_reason: p.reason,
    }
  };
});

const items = $input.all();

const batchSize = 10;
const batches = [];

for (let i = 0; i < items.length; i += batchSize) {
  const batch = items.slice(i, i + batchSize);

  batches.push({
    json: {
      candidates: batch.map(item => item.json)
    }
  });
}

return batches;

