const items = $input.all();

const results = [];

for (const item of items) {
  const rawText =
    item.json.candidates?.[0]?.content?.parts?.[0]?.text ?? '';

  if (!rawText) {
    continue;
  }

  const cleaned = rawText
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();

  let parsed;

  try {
    parsed = JSON.parse(cleaned);
  } catch (error) {
    throw new Error(`Invalid Gemini JSON: ${error.message}`);
  }

  const reviews = Array.isArray(parsed.reviews)
    ? parsed.reviews
    : [];

  for (const review of reviews) {
    results.push({
      json: {
        user_id: review.user_id,
        product_id: Number(review.product_id),
        decision: review.decision,
        reason: review.reason,
      }
    });
  }
}

return results;
